p=pathlib.Path(__file__).parent;q=p.parent/'early-confluence-696c646';read=lambda n:json.loads((p/n).read_text());key=lambda c:json.dumps({k:v for k,v in c.items() if k!='handle'},sort_keys=True,separators=(',',':'))
a=read('baseline-inventory.json')['colliders'];b=read('candidate-inventory.json')['colliders'];ca=collections.Counter(map(key,a));cb=collections.Counter(map(key,b));adds=[json.loads(s) for s in (cb-ca).elements()];rem=[json.loads(s) for s in (ca-cb).elements()]
source="""export function reconcileOrderedWorld(g,R){
const canonical=o=>Array.isArray(o)?o.map(canonical):o&&typeof o==='object'?Object.fromEntries(Object.keys(o).sort().map(k=>[k,canonical(o[k])])):o;
const key=o=>JSON.stringify(canonical(o));
const describe=c=>({shape:c.shape,p:c.translation(),q:c.rotation(),sensor:c.isSensor(),friction:c.friction(),restitution:c.restitution(),parent:c.parent()?.handle??null,hit:g.hitObjects.get(c.handle)??null});
const additions=ADDITIONS, removals=REMOVALS, removeKeys=new Set(removals.map(key)),obsolete=[];g.world.forEachCollider(c=>{if(removeKeys.has(key(describe(c))))obsolete.push(c);});if(obsolete.length!==7)throw Error('Unexpected obsolete collider count '+obsolete.length);
const added=[];for(const p of additions){if(p.parent!==null)throw Error('No body alteration permitted');const s=p.shape;let d;if(s.type===1)d=R.ColliderDesc.cuboid(s.halfExtents.x,s.halfExtents.y,s.halfExtents.z);else if(s.type===2)d=R.ColliderDesc.capsule(s.halfHeight,s.radius);else if(s.type===10)d=R.ColliderDesc.cylinder(s.halfHeight,s.radius);else throw Error('Unexpected new shape');d.setTranslation(p.p.x,p.p.y,p.p.z).setRotation(p.q).setSensor(p.sensor).setFriction(p.friction).setRestitution(p.restitution);const c=g.world.createCollider(d);if(p.hit)g.hitObjects.set(c.handle,p.hit);added.push(c);}
const oldHandles=new Set(obsolete.map(c=>c.handle));for(const c of obsolete){g.hitObjects.delete(c.handle);g.world.removeCollider(c,true);}g.ramp.colliders=g.ramp.colliders.filter(c=>!oldHandles.has(c.handle));g.ramp.supportColliders=g.ramp.supportColliders.filter(c=>!oldHandles.has(c.handle));g.orderedDiagnostic={added:added.length,removed:obsolete.length};
const actual=[];g.world.forEachCollider(c=>actual.push(key(describe(c))));const expected=EXPECTED.map(key).sort();actual.sort();if(JSON.stringify(actual)!==JSON.stringify(expected))throw Error('Final collider multiset mismatch');
}
""".replace('ADDITIONS',json.dumps(adds,separators=(',',':'))).replace('REMOVALS',json.dumps(rem,separators=(',',':'))).replace('EXPECTED',json.dumps([{k:v for k,v in c.items() if k!='handle'} for c in b],separators=(',',':')))
